#pragma once

#include <windows.h>
#include <psapi.h>
#pragma comment(lib,"psapi.lib")

#include <string>
#include <vector>
#include <set>

#include "hh_params.h"
#include "hh_report.h"


typedef enum single_status {
    SSCAN_ERROR1 = (-2),
    SSCAN_ERROR0 = (-1),
    SSCAN_NOT_MATCH = 0,
    SSCAN_IGNORED = 1,
    SSCAN_SUCCESS = 2,
    SSCAN_READY = 3
} t_single_scan_status;

class HHScanner {
public:
    // is the scanner best suited for the OS bitness
    static bool isScannerCompatibile();
    static t_single_scan_status shouldScanProcess(const hh_params& hh_args, const time_t hh_initTime, const DWORD pid, const WCHAR* exe_file);

    HHScanner(t_hh_params& _args, time_t _initTime = 0);

    HHScanReport* scan();
    bool writeToLog(HHScanReport* hh_report);
    void summarizeScan(HHScanReport* hh_report, const pesieve::t_results_filter rfilter);

protected:
    void printScanRoundStats(size_t found, size_t ignored_count, size_t not_matched_count);
    size_t scanProcesses(HHScanReport &my_report);
    void printSingleReport(pesieve::t_report& report);

    t_single_scan_status scanNextProcess(DWORD pid, WCHAR* image_buf, HHScanReport &report);
    void initOutDir(time_t scan_time, pesieve::t_params &pesieve_args);

    t_hh_params &hh_args;
    std::string outDir;

    // time when HollowsHunter was initialized
    time_t initTime;
    bool isScannerWow64;
};


// Global arguments
extern t_hh_params g_hh_args;
#pragma once

#include <pe_sieve_api.h>
#include <string>
#include <set>

#define TIME_UNDEFINED LONGLONG(-1)
#define HH_DEFAULT_DIR "hollows_hunter.dumps"


typedef enum {
    CACHE_DISABLED = 0,  ///< cache always disabled
    CACHE_AUTO,          ///< autodetect if cache should be enabled
    CACHE_ENABLED,       ///< cache always enabled
    CACHE_MODES_COUNT
} t_cache_mode;

typedef enum {
    PROCESS_ALL = 0,
    PROCESS_32BIT = 1,
    PROCESS_64BIT = 2,
    PROCESS_TYPES_COUNT
} t_process_type;

//HollowsHunter's parameters:
typedef struct hh_params
{
public:
    std::string out_dir;
    bool unique_dir;
    bool loop_scanning;
    bool etw_scan;
    bool suspend_suspicious;
    bool kill_suspicious;
    bool quiet;
    bool log;
    bool json_output;
    LONGLONG ptimes;
    t_cache_mode cache_mode;
    std::set<std::wstring> names_list;
    std::set<long> pids_list;
    std::set<std::wstring> ignored_names_list;
    t_process_type process_arch;
    pesieve::t_params pesieve_args; //PE-sieve parameters

    void init();
    hh_params& operator=(const hh_params& other);

} t_hh_params;

#include "hh_params.h"

void hh_params::init()
{
    //reset PE-sieve params:
    memset(&pesieve_args, 0, sizeof(pesieve::t_params));

    //reset output path:
    out_dir = HH_DEFAULT_DIR;
    cache_mode = CACHE_AUTO;
    pesieve_args.quiet = true;
    pesieve_args.no_hooks = true;
    pesieve_args.results_filter = pesieve::SHOW_SUSPICIOUS;

    suspend_suspicious = false;
    kill_suspicious = false;
    loop_scanning = false;
    etw_scan = false;
    unique_dir = false;

    quiet = false;
    log = false;
    json_output = false;
    process_arch = PROCESS_ALL;
    ptimes = TIME_UNDEFINED;
}

hh_params& hh_params::operator=(const hh_params& other)
{
    //copy PE-sieve params:
    ::memcpy(&pesieve_args, &other.pesieve_args, sizeof(pesieve::t_params));

    // copy HHParams
    this->out_dir = other.out_dir;
    this->cache_mode = other.cache_mode;

    this->suspend_suspicious = other.suspend_suspicious;
    this->kill_suspicious = other.kill_suspicious;
    this->loop_scanning = other.loop_scanning;
    this->etw_scan = other.etw_scan;
    this->unique_dir = other.unique_dir;

    this->quiet = other.quiet;
    this->log = other.log;
    this->json_output = other.json_output;
    this->ptimes = other.ptimes;

    // copy lists:
    this->names_list = other.names_list;
    this->pids_list = other.pids_list;
    this->ignored_names_list = other.ignored_names_list;
    this->process_arch = other.process_arch;
    return *this;
}

#pragma once

#include <time.h>

#include <windows.h>
#include <pe_sieve_api.h>
#include <map>
#include <vector>

#include "hh_params.h"

class HHScanReport
{
public:
    HHScanReport(DWORD start_tick, time_t start_time)
        : startTick(start_tick), endTick(0),
        startTime(start_time), endTime(0)
    {
    }

    bool setEndTick(DWORD end_tick, time_t end_time)
    {
        if (end_tick < this->startTick) {
            return false;
        }
        this->endTick = end_tick;
        this->endTime = end_time;
        return true;
    }

    DWORD getScanTime() const
    {
        if (startTick == 0 || endTick == 0) return 0;
        return (this->endTick - this->startTick);
    }

    bool appendReport(pesieve::t_report &scan_report, const std::wstring &img_name);

    size_t countReports(const pesieve::t_results_filter rfilter) const
    {
        if (rfilter == pesieve::SHOW_NONE) {
            return 0;
        }
        if (rfilter == pesieve::SHOW_ALL) {
            return countTotal(false);
        }
        if (rfilter == pesieve::SHOW_SUCCESSFUL_ONLY) {
            return countTotal(true);
        }
        size_t total = 0;
        if (rfilter & pesieve::SHOW_ERRORS) {
            total += failed.size();
        }
        if (rfilter & pesieve::SHOW_SUSPICIOUS) {
            total += suspicious.size();
        }
        return total;
    }

    size_t countTotal(bool successfulOnly = true) const
    {
        size_t total = pidToReport.size();
        if (successfulOnly) {
            total -= failed.size();
        }
        return total;
    }

    void toString(std::wstringstream &stream, const pesieve::t_results_filter rfilter);

protected:
    size_t reportsToString(std::wstringstream &stream, const pesieve::t_results_filter rfilter);

    size_t toJSON(std::wstringstream &stream, const t_hh_params &params);
    size_t reportsToJSON(std::wstringstream &stream, size_t level, const t_hh_params &params);

    time_t startTime;
    time_t endTime;

    DWORD startTick;
    DWORD endTick;

    std::map<DWORD, pesieve::t_report> pidToReport;
    std::map<DWORD, std::wstring> pidToName;
    std::vector<DWORD> suspicious;
    std::vector<DWORD> failed;
    friend class HHScanner;
};
