    if (report.errors == pesieve::ERROR_SCAN_FAILURE) {
        const std::lock_guard<std::mutex> stdOutLock(g_stdOutMutex);
        WORD old_color = hh::util::set_color(MAKE_COLOR(SILVER, DARK_RED));
