        std::cout << "[!] Partial scan: " << std::dec << report.pid << " : " << (report.is_64bit ? 64 : 32) << "b";
        hh::util::set_color(old_color);
        std::cout << std::endl;
    }
#endif
    if (report.suspicious) {
