            headers->getBool("nt_hdr_modified", false) ||
            headers->getBool("sec_hdr_modified", false) ||
            headers->getBool("ep_modified", false);
        if (out.module_file.empty()) {
            out.module_file = headers->getString("module_file");
        }
    }

    const JsonValue* code = entry.get("code_scan");
    if (code) {
        out.has_code_scan = true;
        if (out.module_file.empty()) out.module_file = code->getString("module_file");
    }

    const JsonValue* iat = entry.get("iat_scan");
    if (iat) {
        out.has_iat_scan = true;
        if (out.module_file.empty()) out.module_file = iat->getString("module_file");
    }

    const JsonValue* workingset = entry.get("workingset_scan");
    if (workingset) {
        out.has_workingset_scan = true;
        if (out.module_file.empty()) out.module_file = workingset->getString("module_file");
    }

    const JsonValue* thread = entry.get("thread_scan");
    if (thread) {
        out.has_thread_scan = true;
        if (out.module_file.empty()) out.module_file = thread->getString("module_file");
    }

    const JsonValue* unreachable = entry.get("unreachable_scan");
    if (unreachable) {
        out.has_unreachable_scan = true;
        if (out.module_file.empty()) out.module_file = unreachable->getString("module_file");
    }

    if (hasKey(entry, "malformed_header")) {
        out.has_malformed_header = true;
        const JsonValue* malformed = entry.get("malformed_header");
        if (malformed && out.module_file.empty()) {
            out.module_file = malformed->getString("module_file");
        }
    }

    // The artefact scanner reuses the workingset_scan block name in this
    // PE-sieve version; mark the artefact flag explicitly when a PE-like
    // implant indicator is present, so classification can distinguish a
    // manual-mapped PE from raw shellcode.
    if (workingset && (hasKey(*workingset, "is_pe") ||
