#pragma once

#include <string>

#include "hh_types.h"
#include "hh_whitelist.h"
#include "hh_signature.h"
#include "hh_postprocessor.h"

namespace hh_white {

// Process-wide context shared by every scan round. It owns the whitelist
// rules, the platform signature verifier and the lazily constructed pipeline.
class HHWhitelistContext {
public:
    HHWhitelistContext();
    ~HHWhitelistContext();

    // Loads the configured whitelist file. Returns the number of rules loaded
    // (0 means either an empty/missing file or a disabled feature).
    size_t configure(const std::string& whitelist_file, bool enabled);

    bool isEnabled() const { return enabled; }
    PostProcessor* getProcessor() { return processor; }
    WhitelistEngine& engine() { return whitelist; }

private:
    bool enabled;
    WhitelistEngine whitelist;
    SignatureVerifier* verifier;
    PostProcessor* processor;
};

} // namespace hh_white

#include "hh_integration.h"

namespace hh_white {

HHWhitelistContext::HHWhitelistContext()
    : enabled(false), verifier(nullptr), processor(nullptr)
{
#ifdef _WIN32
    verifier = new WinSignatureVerifier();
#else
    // Off-Windows builds (unit tests) inject their own verifier; leave null.
    verifier = nullptr;
#endif
}

HHWhitelistContext::~HHWhitelistContext()
{
    delete processor;
    delete verifier;
}

size_t HHWhitelistContext::configure(const std::string& whitelist_file, bool enabled_flag)
{
    enabled = enabled_flag && !whitelist_file.empty();
    size_t loaded = 0;
    if (enabled) {
        loaded = whitelist.loadFromFile(whitelist_file);
        // A configured but unreadable/empty file must not silently disable
        // suppression guarantees: stay enabled with zero rules (nothing is
        // suppressed, all findings remain visible).
        enabled = true;
    }
    delete processor;
    if (verifier) {
        processor = new PostProcessor(whitelist, *verifier, enabled);
    }
    return loaded;
}

} // namespace hh_white

