+            if (!engine.getRules()[i].signer.empty()) {
+                rule = engine.getRules()[i];
+                break;
+            }
+        }
+        CHECK_EQ((int)engine.evaluate(f, rule), (int)WL_SIGNER_MATCH);
+    }
