        return "";
    }

    std::string signer;
    DWORD signer_size = 0;
    if (CryptMsgGetParam(message, CMSG_SIGNER_INFO_PARAM, 0, nullptr, &signer_size) &&
        signer_size > 0) {
        std::vector<BYTE> buffer(signer_size);
