        if (CryptMsgGetParam(message, CMSG_SIGNER_INFO_PARAM, 0,
                             signer_info, &signer_size)) {
            CERT_INFO cert_info;
            memset(&cert_info, 0, sizeof(cert_info));
            cert_info.Issuer = signer_info->Issuer;
            cert_info.SerialNumber = signer_info->SerialNumber;
